Func<dynamic, Context, CancellationToken, Task> HandleAsync = (view, ctx, ct) =>
{
    if (view.Host is not Orc.Cards.Card host) { return Task.CompletedTask; }

    // 参值运行期读取（每次伤害结算时读当前值——改写后随动；null／0＝无减伤）。
    var armor = Orc.Game.Cards.KeywordRules.GetKeywordValue(host, Orc.Game.Cards.KeywordIds.Armor);
    if (armor is null || armor <= 0) { return Task.CompletedTask; }

    // 只减「打在本卡身上」的那一向（反击方向是另一次结算，Target 同样指向本卡）。
    if (!object.ReferenceEquals(view.Target, host)) { return Task.CompletedTask; }

    // 判定读点：攻击者侧「无视重甲」——默认不无视（ArmorRules 单源）。
    if (view.Source is Orc.Game.Cards.UnitCard attacker
        && Orc.Game.Cards.ArmorRules.IgnoresArmor(attacker))
    {
        return Task.CompletedTask;
    }

    view.Amount = Math.Max(0, ((int)view.Amount) - armor.Value);
    return Task.CompletedTask;
};
